mapper.select:
/* kr.happyjob.study.vo.requests.historyList2 */ SELECT U.team AS team, U.name AS name, P.product_name AS productName, PD.rental_date AS rentalDate, PD.return_date AS returnDate, PD.product_detail_code AS productDetailCode, PD.product_no AS productNo, PD.product_state AS status, CC.category_name FROM tb_product_detail PD INNER JOIN tb_product_info P ON PD.product_no = P.product_no INNER JOIN tb_userinfo U ON PD.loginID = U.loginID INNER JOIN tb_category_code as CC ON PD.category_code = CC.category_code
/* 괄호를 통해 해당 평가가 먼저 되게 함, () -> NOT-> AND -> OR 순으로 평가됨*/ (PD.rental_date IS NOT NULL OR PD.return_date IS NOT NULL)
/* 컨트롤러에서 이 값을 넣으면 일반유저, 없으면 관리자*/ AND PD.loginID = #{loginID}
/*searchMajorSel, searchSubSel, searchTitle*/
AND U.team LIKE CONCAT('%',#{searchSubSel},'%')
AND U.team IS NULL
AND U.name LIKE CONCAT('%',#{searchSubSel},'%')
AND U.name IS NULL
AND CC.category_name LIKE CONCAT('%',#{searchSubSel},'%')
AND CC.category_name IS NULL
AND ( PD.product_state LIKE CONCAT('%',#{searchSubSel_N},'%') OR PD.product_state LIKE CONCAT('%',#{searchSubSel_R},'%') )
AND PD.product_state LIKE CONCAT('%',#{searchSubSel},'%')
AND PD.product_state IS NULL
AND PD.product_state IN ('Y', 'N', 'R')
ORDER BY PD.rental_date DESC LIMIT #{pageIndex}, #{pageSize}

/* kr.happyjob.study.vo.requests.historyCnt */
SELECT
    COUNT(*)
FROM tb_product_detail PD
INNER JOIN tb_product_info P ON PD.product_no = P.product_no
INNER JOIN tb_userinfo U ON PD.loginID = U.loginID
INNER JOIN tb_category_code as CC ON PD.category_code = CC.category_code

    /* 괄호를 통해 해당 평가가 먼저 되게 함, () -> NOT-> AND -> OR 순으로 평가됨*/
    (PD.rental_date IS NOT NULL OR PD.return_date IS NOT NULL)

        /* 컨트롤러에서 이 값을 넣으면 일반유저, 없으면 관리자*/
        AND PD.loginID = #{loginID}

    /*searchMajorSel, searchSubSel, searchTitle*/



                /* 소속팀 쿼리*/

                    AND U.team LIKE CONCAT('%',#{searchSubSel},'%')


                    AND U.team IS NULL



                /* 대여자 쿼리*/

                    AND U.name LIKE CONCAT('%',#{searchSubSel},'%')


                    AND U.name IS NULL



                /* IT 장비 이름 쿼리*/

                    AND CC.category_name LIKE CONCAT('%',#{searchSubSel},'%')


                    AND CC.category_name IS NULL



                /* 장비 상태 쿼리*/


                        AND ( PD.product_state LIKE CONCAT('%',#{searchSubSel_N},'%') OR PD.product_state LIKE CONCAT('%',#{searchSubSel_R},'%') )


                        AND PD.product_state LIKE CONCAT('%',#{searchSubSel},'%')





            AND PD.product_state IN ('Y', 'N', 'R')

mapper.delete:
/* kr.happyjob.study.vo.requests.deleteHistory*/
DELETE
FROM tb_product_detail
WHERE product_no = #{productNo}
  AND product_detail_code = #{productDetailCode}
